0|# THE ONLY AUTOMATION. Two jobs, and why they are shaped this way.
#
# pull_request_target runs THIS file from main (the trusted copy), never a PR's edited version.
# (With plain pull_request a PR runs its own workflow files: an attacker could rewrite the check
# to always pass.)
#
# judge   has ZERO permissions: an empty token and no secrets. It is the only place a contributor's
#         code ever executes (inside headless Chrome, for the brick test), so there is nothing in it
#         to steal. Its tooling comes from main: the checkout is main, the PR is fetched as data and
#         only its entities/ and assets/ files are placed into the tree.
# merge   holds write access and never checks out or runs anything. It merges exactly the commit
#         that was judged, only if judge passed; a push after judging makes the merge fail.
#
# No Cloudflare credential exists in this repository: Cloudflare Pages pulls and builds it itself.
name: gatekeeper
on:
  pull_request_target:
    types: [opened, synchronize, reopened]
permissions: {}
concurrency:
  group: gatekeeper-${{ github.event.pull_request.number }}
  cancel-in-progress: true
jobs:
  judge:
    runs-on: ubuntu-latest
    permissions: {}
    steps:
      - name: Check out main (trusted tooling only)
        uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262  # v4
        with:
          ref: ${{ github.event.repository.default_branch }}
          fetch-depth: 0
          persist-credentials: false
      - name: Fetch the PR as data
        env:
          HEAD_REPO: ${{ github.event.pull_request.head.repo.clone_url }}
          HEAD_SHA: ${{ github.event.pull_request.head.sha }}
        run: git fetch --no-tags "$HEAD_REPO" "$HEAD_SHA"
      - name: The Law (static)
        env:
          HEAD_SHA: ${{ github.event.pull_request.head.sha }}
        run: node scripts/check-pr.mjs "$(git rev-parse HEAD)" "$HEAD_SHA"
      - name: Place the PR's habitat files into main's tree
        env:
          HEAD_SHA: ${{ github.event.pull_request.head.sha }}
        run: git checkout "$HEAD_SHA" -- entities assets
      - name: Install the brick test's one dependency (pinned, from main's lockfile)
        run: npm ci --ignore-scripts --no-audit --no-fund
      - name: The brick test (the world must keep living)
        run: node scripts/brick-test.mjs
  merge:
    needs: judge
    runs-on: ubuntu-latest
    permissions:
      contents: write
      pull-requests: write
    steps:
      - name: Merge exactly what was judged
        env:
          GH_TOKEN: ${{ secrets.GITHUB_TOKEN }}
          PR: ${{ github.event.pull_request.number }}
          HEAD_SHA: ${{ github.event.pull_request.head.sha }}
        run: gh pr merge "$PR" --repo "$GITHUB_REPOSITORY" --squash --match-head-commit "$HEAD_SHA"

1|// Cloudflare Pages build: the manifest, then ONLY the site's files into dist/. The repo root (the
// machinery, the lockfile, .github) is never published. Reads file names; never runs an entity.
import { execFileSync } from 'node:child_process';
import { cpSync, mkdirSync, rmSync, existsSync } from 'node:fs';
execFileSync('node', ['scripts/build-manifest.mjs'], { stdio: 'inherit' });
rmSync('dist', { recursive: true, force: true });
mkdirSync('dist');
for (const f of ['index.html', '404.html', 'guard.js', 'shell.js', 'shell.css', 'game.html', 'game.css', 'engine.js', 'manifest.js', '_headers']) cpSync(f, `dist/${f}`);
for (const d of ['entities', 'assets', 'lib']) if (existsSync(d)) cpSync(d, `dist/${d}`, { recursive: true, filter: s => !/\/\.[^/]*$/.test(s) });
console.log('dist/ built');

2|// Deploy step: every file in entities/ is loaded in filename order, so ordering is deterministic and
// no contributor ever edits a shared list (which would conflict and, under the Law of Conservation,
// would count as a deletion). async = false keeps dynamically inserted scripts in insertion order.
//
// QUARANTINE.md (Keepers only) lists entities that would brick the world for everyone: an entity
// that navigates its frame away or loops forever never yields, so no countermeasure can answer it.
// A quarantined file is NOT deleted; it stays in the repo, dormant. Nothing else is ever skipped.
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
const quarantined = new Set(existsSync('QUARANTINE.md')
  ? [...readFileSync('QUARANTINE.md', 'utf8').matchAll(/^- `?(\d{4}-[a-z0-9-]+\.js)`?/gm)].map(m => m[1]) : []);
// lib/ (shared building blocks) loads before entities/, so creatures can use what lib provides.
const libs = existsSync('lib') ? readdirSync('lib').filter(f => /^[a-z0-9-]+\.js$/.test(f)).sort().map(f => 'lib/' + f) : [];
const ents = readdirSync('entities').filter(f => /^[\w.-]+\.js$/.test(f) && !quarantined.has(f)).sort().map(f => 'entities/' + f);
const files = [...libs, ...ents];
writeFileSync('manifest.js',
  `// GENERATED at deploy from entities/. Do not commit.\n` +
  `for (const f of ${JSON.stringify(files)}) {\n` +
  `  const s = document.createElement('script');\n` +
  `  s.src = f; s.async = false;\n` +
  `  document.body.appendChild(s);\n` +
  `}\n`);
console.log(`manifest: ${libs.length} lib, ${ents.length} entities${quarantined.size ? `, ${quarantined.size} quarantined` : ''}`);

3|// Content gates, shared by the gatekeeper and the Keeper's blocklist builder.
//
// WORDS: LDNOOBW "en" (github.com/LDNOOBW/List-of-Dirty-Naughty-Obscene-and-Otherwise-Bad-Words,
// CC-BY-4.0, pinned in blocklist.json), minus SWEAR_ALLOW below. Stored only as hashes, so this
// public repo never publishes the list and nobody can read it to route around it.
// Matching is on whole words after normalisation, so a word that merely CONTAINS a blocked string
// ("analysis", "cockpit", "Scunthorpe") is never flagged.
import { createHash } from 'node:crypto';

// Graham, 2026-09-26: "swearing is probably fine". Ordinary swears stay allowed; slurs and sexual
// content do not. Edit this list, then rerun scripts/build-blocklist.mjs.
export const SWEAR_ALLOW = [
  'fuck', 'fucking', 'fucked', 'fucker', 'motherfucker', 'shit', 'shitty', 'bullshit', 'crap',
  'damn', 'goddamn', 'hell', 'ass', 'asshole', 'bastard', 'piss', 'pissed', 'bloody', 'bollocks',
  'arse', 'arsehole', 'wtf', 'screw', 'sucks',
];

const LEET = { '0': 'o', '1': 'i', '3': 'e', '4': 'a', '5': 's', '7': 't', '8': 'b', '@': 'a', '$': 's', '!': 'i', '|': 'i' };

/**
 * Words as a reader sees them: camelCase and snake_case split, lowercased, leetspeak undone.
 * Letter swaps apply ONLY to tokens that already contain a letter: measured on TypeScript's own
 * compiler, swapping inside plain numbers turned 8008 into "boob" and 717 into "tit".
 */
export function words(text) {
  const out = [];
  for (const tok of text.replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase().match(/[a-z0-9@$!|]+/g) ?? []) {
    if (!/[a-z]/.test(tok)) continue;
    for (const w of tok.replace(/[0134578@$!|]/g, c => LEET[c]).match(/[a-z]+/g) ?? []) out.push(w);
  }
  return out;
}

export const hashOf = s => createHash('sha256').update(s).digest('hex').slice(0, 20);

/** Every 1..6 word window, hashed, so multi-word entries match too. */
export function* windows(ws) {
  for (let i = 0; i < ws.length; i++)
    for (let n = 1; n <= 6 && i + n <= ws.length; n++) yield ws.slice(i, i + n).join(' ');
}

// LINKS: only inside string literals and comments, which is where a link has to live. Measured
// on real code first: a bare domain pattern over JS fires on `window.top`, `config.io`, `this.dev`.
export const LINK_PATTERNS = [
  /\bhttps?:\/\//i, /\bwww\./i, /\b(discord\.gg|discord\.com\/invite|t\.me|bit\.ly|tinyurl\.com|goo\.gl|linktr\.ee)\b/i,
  /\b[a-z0-9-]{2,}\.(com|net|org|io|gg|xyz|ru|cn|tk|ly|me|co|app|dev|link|info|biz|site|online|shop|top|club|live|tv|us|uk|de|fr|onion)\b/i,
];

/** String literals and comments in a line of JS/CSS (approximate, and deliberately so). */
export function stringsAndComments(line) {
  const out = [];
  const re = /\/\/.*$|\/\*.*?(\*\/|$)|'(?:\\.|[^'\\])*'|"(?:\\.|[^"\\])*"|`(?:\\.|[^`\\])*`/g;
  let m; while ((m = re.exec(line))) out.push(m[0]);
  return out;
}

4|// The brick test. Boots the world AS IT WOULD BE after merging, THE REAL WAY (front page, Enter,
// the sandboxed frame, every _headers rule applied per path exactly as Cloudflare does), and fails
// if the world stops living for everyone:
//   - it navigates away, or never loads
//   - it stops advancing (an endless loop; evaluate never returns)
//   - it crawls (below 10 frames per second)
//   - it balloons (over 512 MB of JavaScript heap)
// Runs ONLY in the workflow's zero-permission job: the one place contributed code executes holds no
// token scopes and no secrets. Usage: node scripts/brick-test.mjs [--chrome /path]
import http from 'node:http';
import { readFileSync, existsSync } from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import puppeteer from 'puppeteer-core';

const root = process.cwd();
const argv = process.argv.slice(2);
const chrome = argv.includes('--chrome') ? argv[argv.indexOf('--chrome') + 1]
  : ['/usr/bin/google-chrome', '/usr/bin/google-chrome-stable', '/usr/bin/chromium'].find(existsSync);
if (!chrome) { console.error('brick-test: no Chrome found (pass --chrome).'); process.exit(2); }

execFileSync('node', ['scripts/build-site.mjs'], { cwd: root, stdio: 'inherit' });
const site = path.join(root, 'dist');

// _headers, parsed the way Pages applies it: every block whose pattern matches contributes, and a
// header named in several blocks is sent several times (browsers enforce every CSP they receive).
const blocks = [];
for (const line of readFileSync(path.join(site, '_headers'), 'utf8').split('\n')) {
  if (/^\//.test(line)) blocks.push({ re: new RegExp('^' + line.trim().replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*') + '$'), headers: [] });
  else if (/^  [A-Za-z-]+: /.test(line) && blocks.length) { const i = line.indexOf(': '); blocks.at(-1).headers.push([line.slice(2, i), line.slice(i + 2)]); }
}
const types = { '.js': 'text/javascript', '.css': 'text/css', '.html': 'text/html' };
const srv = http.createServer((req, res) => {
  const url = decodeURIComponent((req.url || '/').split('?')[0]);
  let rel = url === '/' ? 'index.html' : url.replace(/^\/+/, '');
  if (!path.extname(rel) && existsSync(path.join(site, rel + '.html'))) rel += '.html'; // Pages serves /game for game.html
  const p = path.join(site, rel);
  if (!p.startsWith(site + path.sep) || !existsSync(p)) { res.writeHead(404); return res.end(); }
  const out = {};
  for (const b of blocks) if (b.re.test(url)) for (const [k, v] of b.headers) (out[k] ??= []).push(v);
  res.writeHead(200, { 'Content-Type': types[path.extname(p)] ?? 'application/octet-stream', ...out });
  res.end(readFileSync(p));
});
await new Promise(r => srv.listen(0, '127.0.0.1', r));
const origin = `http://127.0.0.1:${srv.address().port}`;

const withTimeout = (p, ms) => Promise.race([p, new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), ms))]);
const problems = [];
const browser = await puppeteer.launch({ executablePath: chrome, headless: true, args: ['--no-sandbox'] });
try {
  const page = await browser.newPage();
  page.setDefaultTimeout(8000);
  await withTimeout(page.goto(`${origin}/`), 10_000).catch(e => problems.push(`the front page did not load: ${e.message}`));
  await withTimeout(page.click('#enter'), 5000).catch(e => problems.push(`could not enter: ${e.message}`));
  await new Promise(r => setTimeout(r, 1500));
  const world = () => page.frames().find(f => f !== page.mainFrame());
  const frameAt = () => withTimeout(world().evaluate(() => (window.THE_GAME ? window.THE_GAME.frame : -1)), 3000);
  const a = await frameAt().catch(() => null);
  await new Promise(r => setTimeout(r, 2000));
  const b = await frameAt().catch(() => null);
  const heapMB = await withTimeout(page.metrics(), 3000).then(m => m.JSHeapUsedSize / 1048576).catch(() => null);
  const topUrl = page.url();
  const frameUrl = world()?.url() ?? '';
  if (!topUrl.startsWith(origin)) problems.push(`the page navigated away (${topUrl.slice(0, 80)}).`);
  else if (!frameUrl.startsWith(origin)) problems.push(`the world navigated away (${frameUrl.slice(0, 80)}).`);
  else if (a === null || b === null) problems.push('the world stopped responding: something is blocking the main thread (an endless loop?).');
  else if (a < 0) problems.push('THE_GAME never started.');
  else if (b - a < 20) problems.push(`the world crawls: ${b - a} frames in 2s (the floor is 20, i.e. 10 fps).`);
  if (heapMB !== null && heapMB > 512) problems.push(`the world uses ${heapMB.toFixed(0)} MB of memory (the ceiling is 512 MB).`);
  if (!problems.length) console.log(`brick-test: alive, ${b - a} frames in 2s, ${heapMB?.toFixed(0) ?? '?'} MB heap.`);
} finally {
  await browser.close().catch(() => {});
  srv.close();
}
if (problems.length) {
  console.log('BRICKED:');
  for (const p of problems) console.log(`  - ${p}`);
  console.log('An entity that stops the world for everyone cannot be answered by a countermeasure, so it cannot merge.');
  process.exit(1);
}

5|// The gatekeeper. Runs on every PR with NO write access; a separate workflow merges only if this
// passed. Usage: node scripts/check-pr.mjs <base-sha> <head-sha>
//
// Enforced here: the Law of Conservation (no deletions, no renames, no edits to existing lines),
// the habitat (only entities/ and assets/), asset size, entity naming. The API lint is a courtesy
// that fails fast with a clear message; the real sandbox is the CSP in _headers, which the browser
// enforces however cleverly a call is disguised.
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { words, windows, hashOf, LINK_PATTERNS, stringsAndComments } from './content-rules.mjs';

const [base, head] = process.argv.slice(2);
if (!base || !head) { console.error('usage: check-pr.mjs <base> <head>'); process.exit(2); }
const git = (...a) => execFileSync('git', a, { encoding: 'utf8', maxBuffer: 64 << 20 });
const range = `${base}...${head}`;
const problems = [];

// THE WORLD: everything that runs INSIDE the sandbox, open to anyone, add-only. Everything else is
// the cage (index.html holds the sandbox attribute, _headers holds the CSP, the workflows and these
// scripts hold the checks) or the law, and stays with the Keepers. Growing the world cannot reach
// outside it: world code runs in <iframe sandbox="allow-scripts"> under a CSP with no network.
const WORLD = /^(entities\/|assets\/|lib\/|engine\.js$|game\.css$)/;

// Every changed path and how it changed. A = added, M = modified, D/R/C/T = forbidden outright.
const status = git('diff', '--name-status', '-M', range).trim().split('\n').filter(Boolean)
  .map(l => { const [s, ...p] = l.split('\t'); return { s, path: p[p.length - 1], from: p[0] }; });
if (status.length === 0) problems.push('The PR changes nothing.');

for (const { s, path, from } of status) {
  if (s.startsWith('D')) problems.push(`${path}: deleted. The Law of Conservation forbids deletion.`);
  else if (s.startsWith('R')) problems.push(`${from} -> ${path}: renamed. A rename deletes the old name.`);
  else if (!['A', 'M'].includes(s)) problems.push(`${path}: change type ${s} is not allowed.`);
  if (!WORLD.test(path)) problems.push(`${path}: part of the cage or the law. The world (engine.js, game.css, entities/, assets/, lib/) is yours to build on; the files that keep it safe belong to the Keepers.`);
  if (/^entities\//.test(path) && !/^entities\/\d{4}-[a-z0-9-]+\.js$/.test(path)) problems.push(`${path}: entity files are named NNNN-short-name.js.`);
  // Assets are MEDIA ONLY. An .html or .svg here would be a live, scriptable page on this domain.
  if (/^assets\//.test(path) && !/^assets\/[a-z0-9-]+\.(png|jpe?g|gif|webp|avif|mp3|ogg|wav|m4a|json|txt)$/.test(path) && !/\/\.gitkeep$/.test(path))
    problems.push(`${path}: assets are media only (png, jpg, gif, webp, avif, mp3, ogg, wav, m4a, json, txt), named in lowercase with hyphens.`);
  if (/^lib\//.test(path) && !/^lib\/[a-z0-9-]+\.js$/.test(path)) problems.push(`${path}: lib files are named short-name.js (lowercase, hyphens).`);
}

// Only ordinary files. A symlink (mode 120000) could point at machinery or at the build machine's
// own files; a submodule (160000) pulls in a whole other repository. Both are refused outright.
for (const line of git('diff', '--raw', '--no-abbrev', range).trim().split('\n').filter(Boolean)) {
  const m = /^:(\d{6}) (\d{6}) \S+ \S+ \S+\t(.+)$/.exec(line);
  if (m && m[2] !== '100644' && m[2] !== '000000') problems.push(`${m[3].split('\t').pop()}: file mode ${m[2]}. Only ordinary files are allowed (no symlinks, submodules or executables).`);
}

// Size of one PR. A world that grows forever still grows one reasonable step at a time.
if (status.length > 20) problems.push(`${status.length} files in one PR. The limit is 20.`);
let addedBytes = 0;
for (const { s, path } of status) if (s === 'A' || s === 'M') { try { addedBytes += Number(git('cat-file', '-s', `${head}:${path}`).trim()); } catch {} }
if (addedBytes > 5 * 1024 * 1024) problems.push(`${(addedBytes / 1048576).toFixed(1)} MB in one PR. The limit is 5 MB.`);

// Line-level conservation. numstat reports an edited line as one deletion plus one addition, so
// "deletions > 0" also catches any change to an existing line. Binary files report "-".
for (const line of git('diff', '--numstat', range).trim().split('\n').filter(Boolean)) {
  const [add, del, path] = line.split('\t');
  if (del !== '-' && Number(del) > 0) problems.push(`${path}: ${del} line(s) removed or changed. Existing lines are permanent; add new code that overrides them instead.`);
  if (add === '-' && /^assets\//.test(path)) {
    const bytes = Number(git('cat-file', '-s', `${head}:${path}`).trim());
    if (bytes > 2 * 1024 * 1024) problems.push(`${path}: ${(bytes / 1048576).toFixed(1)} MB. Assets are 2 MB at most.`);
  }
}
for (const { s, path } of status) {
  if (s === 'A' && /^assets\//.test(path)) {
    const bytes = Number(git('cat-file', '-s', `${head}:${path}`).trim());
    if (bytes > 2 * 1024 * 1024 && !problems.some(p => p.startsWith(path))) problems.push(`${path}: ${(bytes / 1048576).toFixed(1)} MB. Assets are 2 MB at most.`);
  }
}

// Courtesy lint over ADDED lines of scripts. Fails fast with a clear reason; the CSP is the wall.
const FORBIDDEN = [
  [/\bfetch\s*\(|XMLHttpRequest|WebSocket|EventSource|sendBeacon|RTCPeerConnection/, 'network access (blocked by the page CSP anyway)'],
  [/\beval\s*\(|new\s+Function\s*\(|\bimport\s*\(|importScripts/, 'dynamic code loading (blocked by the page CSP anyway)'],
  [/WebAssembly/, 'WebAssembly (the classic crypto-miner vehicle)'],
  [/localStorage\.clear|indexedDB\.deleteDatabase|document\.cookie/, 'wiping or reading visitor storage'],
  [/window\.open\s*\(|location\s*=|location\.(href|replace|assign)/, 'navigating the visitor away'],
];
const patch = git('diff', '-U0', range, '--', 'entities', 'lib', 'engine.js');
let file = '';
for (const l of patch.split('\n')) {
  if (l.startsWith('+++ ')) { file = l.slice(6); continue; }
  if (!l.startsWith('+') || l.startsWith('+++')) continue;
  for (const [re, why] of FORBIDDEN) if (re.test(l)) problems.push(`${file}: ${why}: ${l.slice(1).trim().slice(0, 80)}`);
}

// CONTENT GATES over every ADDED line of text in the world: links and spam (inside strings and
// comments, where a link has to live; whole lines for .txt/.json), and the hashed word list
// (scripts/blocklist.json; ordinary swears are allowed, see content-rules.mjs). Text assembled at
// runtime can dodge a static check; nothing in the world can send anyone anywhere regardless.
const block = new Set(JSON.parse(readFileSync(new URL('./blocklist.json', import.meta.url), 'utf8')).hashes);
const textPatch = git('diff', '-U0', range, '--', 'entities', 'lib', 'engine.js', 'game.css', 'assets/*.txt', 'assets/*.json');
let tfile = '';
const flagged = new Set();
for (const l of textPatch.split('\n')) {
  if (l.startsWith('+++ ')) { tfile = l.slice(6); continue; }
  if (!l.startsWith('+') || l.startsWith('+++')) continue;
  const line = l.slice(1);
  const linkScope = /\.(txt|json)$/.test(tfile) ? [line] : stringsAndComments(line);
  if (linkScope.some(sc => LINK_PATTERNS.some(re => re.test(sc))) && !flagged.has(tfile + ':link')) {
    flagged.add(tfile + ':link');
    problems.push(`${tfile}: contains a link or web address. THE GAME is links-free: nothing in it can send anyone anywhere.`);
  }
  for (const w of windows(words(line))) {
    if (block.has(hashOf(w)) && !flagged.has(tfile + ':word')) {
      flagged.add(tfile + ':word');
      problems.push(`${tfile}: contains a word on the blocked list (slurs and sexual content; ordinary swearing is fine).`);
    }
  }
}

if (problems.length) {
  console.log(`REJECTED (${problems.length}):`);
  for (const p of problems) console.log(`  - ${p}`);
  process.exit(1);
}
console.log(`ACCEPTED: ${status.length} file(s) added or extended, nothing removed.`);

6|// THE GUARD. The first script game.html runs, before the engine or any contributed code. The world
// only ever runs inside index.html's sandboxed frame. Opened any other way (someone links straight
// to /game), it stops loading everything after this line and goes to the front page instead, so
// contributed code never runs outside the cage. game.html and this file are Keeper-only.
if (window.top === window.self) {
  window.stop();
  document.documentElement.innerHTML = '';
  location.replace('/');
  throw new Error('THE GAME only runs inside its frame.');
}

7|# THE SANDBOX, enforced by the browser rather than by a linter. Two layers:
#  1. game.html runs inside <iframe sandbox="allow-scripts"> (index.html): no cookies, no storage,
#     no top-level navigation, no popups, no forms, no downloads.
#  2. This CSP on every page: no network, no outside scripts, no eval, and frames may only load
#     from this site, so the caged frame cannot navigate itself off it either.
# A contributor cannot edit this file (machinery; the gatekeeper rejects it), and a second CSP
# added anywhere could only tighten this one: browsers enforce every policy they receive.
/*
